/**
 * Number One Adapter — Bridge between MSN-0034 Python Engine and Phase 2 API
 *
 * Purpose: Connect the existing MSN-0034 Number One coordination engine
 *          outputs to the Phase 2 backend API.
 *
 * Design:
 * - Reads JSON files generated by Number One Python engine
 * - Fails closed when required Number One files are unavailable
 * - Provides standardized interface for coordination API routes
 * - No database, no queues, no authentication added
 * - Simple file-based data source
 *
 * Data Source Mapping:
 * ┌─────────────────────────────────────────────────────┐
 * │ Number One Python Engine (MSN-0034)                 │
 * │ /core/coordination/number_one.py                    │
 * └─────────────────┬───────────────────────────────────┘
 *                   │ (Exports JSON outputs)
 *                   ↓
 * ┌─────────────────────────────────────────────────────┐
 * │ JSON Data Files                                      │
 * │ /core/coordination/outputs/                         │
 * │   - daily_brief.json                               │
 * │   - work_queue.json                                │
 * │   - escalations.json                               │
 * └─────────────────┬───────────────────────────────────┘
 *                   │ (Reads via this adapter)
 *                   ↓
 * ┌─────────────────────────────────────────────────────┐
 * │ Phase 2 API Backend (Node.js)                       │
 * │ /backend/api/coordination.js                        │
 * └─────────────────────────────────────────────────────┘
 */

const fs = require('fs');
const path = require('path');

/**
 * Number One Adapter Class
 *
 * Reads coordination data from JSON files generated by Number One engine.
 * Throws an explicit unavailable error if files are missing or invalid.
 */
class NumberOneAdapter {
  constructor(dataDir = '../../../../core/coordination/outputs') {
    this.dataDir = path.resolve(__dirname, dataDir);
    this.debug = true;
    this.lastLoadTime = null;
    this.cache = {
      brief: null,
      queue: null,
      escalations: null
    };
  }

  /**
   * Get daily coordination brief from Number One
   * @returns {object} Coordination brief data
   */
  getDailyBrief() {
    try {
      const filePath = path.join(this.dataDir, 'daily_brief.json');
      if (fs.existsSync(filePath)) {
        const fileData = fs.readFileSync(filePath, 'utf8');
        const brief = JSON.parse(fileData);
        this.log('📋 Loaded daily brief from Number One');
        return this.transformBriefFromNumberOne(brief);
      }
    } catch (error) {
      this.log(`⚠️  Failed to load daily brief: ${error.message}`);
    }

    const error = new Error('Number One daily brief data is unavailable');
    error.code = 'NUMBER_ONE_UNAVAILABLE';
    throw error;
  }

  /**
   * Get prioritized work queue from Number One
   * @returns {object} Work queue data
   */
  getWorkQueue() {
    try {
      const filePath = path.join(this.dataDir, 'work_queue.json');
      if (fs.existsSync(filePath)) {
        const fileData = fs.readFileSync(filePath, 'utf8');
        const queue = JSON.parse(fileData);
        this.log('📋 Loaded work queue from Number One');
        return this.transformQueueFromNumberOne(queue);
      }
    } catch (error) {
      this.log(`⚠️  Failed to load work queue: ${error.message}`);
    }

    const error = new Error('Number One work queue data is unavailable');
    error.code = 'NUMBER_ONE_UNAVAILABLE';
    throw error;
  }

  /**
   * Get XO escalations from Number One
   * @returns {object} Escalations data
   */
  getEscalations() {
    try {
      const filePath = path.join(this.dataDir, 'escalations.json');
      if (fs.existsSync(filePath)) {
        const fileData = fs.readFileSync(filePath, 'utf8');
        const escalations = JSON.parse(fileData);
        this.log('📋 Loaded escalations from Number One');
        return this.transformEscalationsFromNumberOne(escalations);
      }
    } catch (error) {
      this.log(`⚠️  Failed to load escalations: ${error.message}`);
    }

    const error = new Error('Number One escalations data is unavailable');
    error.code = 'NUMBER_ONE_UNAVAILABLE';
    throw error;
  }

  /**
   * Check if Number One data is available
   * @returns {boolean} True if data files exist
   */
  isDataAvailable() {
    try {
      const briefPath = path.join(this.dataDir, 'daily_brief.json');
      const queuePath = path.join(this.dataDir, 'work_queue.json');
      const escalationsPath = path.join(this.dataDir, 'escalations.json');

      return (
        fs.existsSync(briefPath) &&
        fs.existsSync(queuePath) &&
        fs.existsSync(escalationsPath)
      );
    } catch {
      return false;
    }
  }

  /**
   * Get data source status
   * @returns {object} Status info
   */
  getStatus() {
    const available = this.isDataAvailable();
    return {
      status: available ? 'LIVE_FROM_NUMBER_ONE' : 'UNAVAILABLE',
      dataDir: this.dataDir,
      filesAvailable: {
        briefPath: path.join(this.dataDir, 'daily_brief.json'),
        queuePath: path.join(this.dataDir, 'work_queue.json'),
        escalationsPath: path.join(this.dataDir, 'escalations.json')
      },
      exists: {
        brief: fs.existsSync(path.join(this.dataDir, 'daily_brief.json')),
        queue: fs.existsSync(path.join(this.dataDir, 'work_queue.json')),
        escalations: fs.existsSync(path.join(this.dataDir, 'escalations.json'))
      }
    };
  }

  // =========================================================================
  // Data Transformation Methods (Number One format → API format)
  // =========================================================================

  /**
   * Transform Number One brief to API format
   */
  transformBriefFromNumberOne(numberOneBrief) {
    return {
      status: 'operational',
      timestamp: new Date().toISOString(),
      dayStarted: new Date().toISOString().split('T')[0],
      systemHealth: numberOneBrief.system_health || 'operational',
      topPriorities: (numberOneBrief.top_priorities || []).length,
      escalations: {
        CRITICAL: (numberOneBrief.escalations || []).filter(e => e.level === 'critical').length,
        HIGH: (numberOneBrief.escalations || []).filter(e => e.level === 'high').length,
        MEDIUM: (numberOneBrief.escalations || []).filter(e => e.level === 'medium').length,
        total: (numberOneBrief.escalations || []).length
      },
      briefItems: (numberOneBrief.top_priorities || []).map(item => ({
        rank: (numberOneBrief.top_priorities || []).indexOf(item) + 1,
        priority: item.priority || 'P1',
        mission: item.mission_id || 'UNKNOWN',
        title: item.title || 'Untitled',
        status: item.status || 'IN_PROGRESS',
        progress: 50, // Placeholder (would need source data)
        blocker: (item.blockers || []).length > 0,
        owner: item.assigned_specialist || 'Unassigned',
        recommendation: `Continue work on ${item.mission_id}`
      })),
      workQueueItems: numberOneBrief.total_missions || 0,
      blockedMissions: numberOneBrief.blocked_count || 0,
      overdueMissions: 0, // Not in Number One, would need source
      recommendations: numberOneBrief.recommended_actions || [],
      generatedBy: 'Number One v1.0.0 (MSN-0034)',
      nextUpdate: new Date(Date.now() + 30000).toISOString()
    };
  }

  /**
   * Transform Number One queue to API format
   */
  transformQueueFromNumberOne(numberOneQueue) {
    // Handle both direct list and wrapped format
    const items = Array.isArray(numberOneQueue) ? numberOneQueue : (numberOneQueue.items || []);

    return {
      status: 'operational',
      timestamp: new Date().toISOString(),
      totalItems: items.length,
      items: items.map((item, index) => ({
        rank: index + 1,
        itemId: `WQ-${String(index + 1).padStart(3, '0')}`,
        title: item.title || `Task ${item.mission_id}`,
        mission: item.mission_id || 'UNKNOWN',
        priority: item.priority || 'P1',
        assignedTo: item.assigned_specialist || 'Unassigned',
        daysRemaining: item.days_remaining || 5,
        estimatedEffort: item.estimated_effort || '8 hours',
        blocker: (item.blockers || []).length > 0,
        specialistRecommendation: item.assigned_specialist || 'TBD'
      })),
      summary: {
        P0Count: items.filter(i => i.priority === 'P0').length,
        P1Count: items.filter(i => i.priority === 'P1').length,
        P2Count: items.filter(i => i.priority === 'P2').length,
        P3Count: items.filter(i => i.priority === 'P3').length,
        blockedCount: items.filter(i => (i.blockers || []).length > 0).length,
        totalEstimatedEffort: '100 hours' // Placeholder
      }
    };
  }

  /**
   * Transform Number One escalations to API format
   */
  transformEscalationsFromNumberOne(numberOneEscalations) {
    const escalations = Array.isArray(numberOneEscalations) ? numberOneEscalations : (numberOneEscalations.escalations || []);

    return {
      status: 'operational',
      timestamp: new Date().toISOString(),
      totalEscalations: escalations.length,
      levelSummary: {
        CRITICAL: escalations.filter(e => e.level === 'critical').length,
        HIGH: escalations.filter(e => e.level === 'high').length,
        MEDIUM: escalations.filter(e => e.level === 'medium').length,
        LOW: escalations.filter(e => e.level === 'low').length
      },
      escalations: escalations.map(esc => ({
        id: `ESC-${esc.mission_id || 'UNKNOWN'}`,
        level: esc.level ? esc.level.toUpperCase() : 'HIGH',
        mission: esc.mission_id || 'UNKNOWN',
        title: esc.reason || 'Escalation Required',
        description: esc.reason || 'Issue requires XO attention',
        createdAt: new Date().toISOString(),
        status: 'PENDING_XO_DECISION',
        owner: 'Number One',
        escalatedBy: 'Number One Coordination Engine',
        options: [
          {
            option: 'A',
            description: esc.recommendation || 'Follow recommendation',
            effort: 'MEDIUM',
            riskLevel: 'MEDIUM',
            timeline: '2-3 days'
          }
        ],
        xoDecisionRequired: true,
        deadlineForDecision: new Date(Date.now() + 259200000).toISOString()
      })),
      recommendations: escalations.map(e => e.recommendation || 'Review escalation'),
      dataSource: 'Number One (MSN-0034)'
    };
  }

  // =========================================================================
  // Utility Methods
  // =========================================================================

  /**
   * Debug logging
   */
  log(message) {
    if (this.debug) {
      console.log(`[NUMBER-ONE-ADAPTER] ${message}`);
    }
  }

  /**
   * Enable/disable debug logging
   */
  setDebug(enabled) {
    this.debug = enabled;
  }
}

module.exports = { NumberOneAdapter };
